section "mod-tome/data/talents/chronomancy/spacetime-weaving.lua"

t("trap", "piège", "_t")
-- texte non traduit
--[==[
t("Dimensional Step", "Dimensional Step", "talent name")
t("You do not have line of sight.", "You do not have line of sight.", "logPlayer")
