section "mod-tome/data/talents/uber/str.lua"

t("Steamroller", "Rouleau Compresseur", "talent name")
t("Irresistible Sun", "Soleil Irrésistible", "talent name")
t("Legacy of the Naloren", "L'Héritage des Nalores", "talent name")
